async function aee(e) {
  const t = new Blob([new Uint8Array(e)]).stream().pipeThrough(new CompressionStream("gzip"));
  return new Uint8Array(await new Response(t).arrayBuffer());
}
async function cee(e) {
  const t = new Blob([new Uint8Array(e)]).stream().pipeThrough(new DecompressionStream("gzip"));
  return new Uint8Array(await new Response(t).arrayBuffer());
}
function lee(e) {
  let t = "";
  for (let n = 0; n < e.length; n++)
    t += String.fromCharCode(e[n]);
  return btoa(t).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}
function uee(e) {
  const t = e.replace(/-/g, "+").replace(/_/g, "/"), n = (4 - t.length % 4) % 4, r = atob(t + "=".repeat(n));
  return Uint8Array.from(r, (i) => i.charCodeAt(0));
}
async function c1e(e) {
  const t = e instanceof Uint8Array ? e : new Uint8Array(e), n = await aee(t);
  return lee(n);
}
async function ag(e) {
  const t = uee(e);
  return cee(t);
}
